<?php
namespace App\Jobs;
use App\Models\Backup;use App\Models\BackupSchedule;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Queue\Queueable;
class DispatchScheduledBackupsJob implements ShouldQueue{use Queueable;public function __construct(){$this->onQueue(config('infrastructure.queues.backups'));}public function handle():void{BackupSchedule::where('enabled',true)->where(fn($q)=>$q->whereNull('next_run_at')->orWhere('next_run_at','<=',now()))->with('deployment')->each(function($schedule){$backup=Backup::create(['tenant_id'=>$schedule->tenant_id,'application_deployment_id'=>$schedule->application_deployment_id,'server_id'=>$schedule->deployment->server_id,'backup_destination_id'=>$schedule->backup_destination_id,'backup_schedule_id'=>$schedule->id,'name'=>$schedule->deployment->name.' '.ucfirst($schedule->backup_type).' '.now()->format('Y-m-d H:i'),'backup_type'=>$schedule->backup_type,'status'=>'pending']);$next=match($schedule->frequency){'hourly'=>now()->addHour(),'weekly'=>now()->addWeek(),default=>now()->addDay()};$schedule->update(['last_run_at'=>now(),'next_run_at'=>$next]);CreateBackupJob::dispatch($backup->id,$backup->tenant_id);});}}
